pub fn checkWrappers(comptime T: type, comptime R: type) !void {
var rec: R = .{};
const t: T = .{ .rec = &rec };
rec.n = 0;
try Launches(T).absorb_mma(t, .{ 32, 1, 4 }, .{
.@"Q" = 4096,
.@"WK" = 4352,
.@"QA" = 4608,
.@"R" = 22,
}, .{
.@"H" = 32,
.@"D" = 256,
.@"LW" = 512,
.@"BM" = 64,
.@"BN" = 128,
.@"BK" = 64,
});
try std.testing.expectEqualStrings("_absorb_mma", rec.launches[0].name);
try std.testing.expectEqual(@as([3]u32, .{ 32, 1, 4 }), rec.launches[0].grid);
try std.testing.expectEqual(@as(usize, 4), rec.launches[0].nargs);
const expected_absorb_mma = [_]aot.Arg{ aot.ptr("Q", "*bf16", 4096), aot.ptr("WK", "*bf16", 4352), aot.ptr("QA", "*bf16", 4608), aot.int("R", 22) };
for (expected_absorb_mma, rec.launches[0].args[0..rec.launches[0].nargs]) |want, got| {
try std.testing.expectEqualStrings(want.name, got.name);
try std.testing.expectEqualDeep(want.value, got.value);
}
rec.n = 0;
try Launches(T).absorb_q(t, .{ 32, 16, 1 }, .{
.@"Q" = 4096,
.@"WK" = 4352,
.@"QA" = 4608,
.@"R" = 1,
}, .{
.@"H" = 32,
.@"D" = 256,
.@"LW" = 512,
.@"BN" = 32,
});
try std.testing.expectEqualStrings("_absorb_q", rec.launches[0].name);
try std.testing.expectEqual(@as([3]u32, .{ 32, 16, 1 }), rec.launches[0].grid);
try std.testing.expectEqual(@as(usize, 4), rec.launches[0].nargs);
const expected_absorb_q = [_]aot.Arg{ aot.ptr("Q", "*bf16", 4096), aot.ptr("WK", "*bf16", 4352), aot.ptr("QA", "*bf16", 4608), aot.int("R", 1) };
for (expected_absorb_q, rec.launches[0].args[0..rec.launches[0].nargs]) |want, got| {
try std.testing.expectEqualStrings(want.name, got.name);
try std.testing.expectEqualDeep(want.value, got.value);
}
rec.n = 0;
try Launches(T).combine_sy(t, .{ 25, 4, 1 }, .{
.@"Y" = 4096,
.@"SY" = 4352,
.@"WTS" = 4609,
.@"OUT" = 4864,
}, .{
.@"D" = 4096,
.@"SLOTS" = 9,
.@"BLOCK" = 1024,
});
try std.testing.expectEqualStrings("_combine_sy", rec.launches[0].name);
try std.testing.expectEqual(@as([3]u32, .{ 25, 4, 1 }), rec.launches[0].grid);
try std.testing.expectEqual(@as(usize, 4), rec.launches[0].nargs);
const expected_combine_sy = [_]aot.Arg{ aot.ptr("Y", "*fp32", 4096), aot.ptr("SY", "*fp32", 4352), aot.ptr("WTS", "*fp32", 4609), aot.ptr("OUT", "*fp32", 4864) };
for (expected_combine_sy, rec.launches[0].args[0..rec.launches[0].nargs]) |want, got| {
try std.testing.expectEqualStrings(want.name, got.name);
try std.testing.expectEqualDeep(want.value, got.value);
}
rec.n = 0;
try Launches(T).conv_shift(t, .{ 34, 12, 1 }, .{
.@"CONV" = 4096,
.@"PROJ" = 4352,
.@"conv_layer" = 36864,
.@"proj_layer" = 201216,
.@"proj_row" = 12576,
